{"command": "python3 -c "
from PIL import Image, ImageOps
im = Image.open('radiograph.jpg').convert('L')
xs=[(330,960),(920,1550),(1500,2130)]
ys={'max':(240,640),'mand':(470,880)}
for i,(x0,x1) in enumerate(xs):
    for k,(y0,y1) in ys.items():
        c=im.crop((x0,y0,x1,y1))
        c=ImageOps.autocontrast(c)
        c=c.resize((c.width*3,c.height*3),Image.LANCZOS)
        c.save(f't_{k}_{i}.png')
        print(k,i,(x0,y0,x1,y1),c.size)
"", "description": "Create 6 tiles at 3x zoom"}

